:root {
  --yellow: #F2C94C;
  --orange: #F97316;
  --teal: #3AADA0;
  --charcoal: #2B2B26;
  --charcoal-soft: #52504A;
  --cream: #FAF7F0;
  --white: #FFFFFF;
}

* { margin: 0; padding: 0; box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  background: var(--white);
  color: var(--charcoal);
  line-height: 1.6;
}
h1, h2, h3 { font-family: 'Playfair Display', Georgia, serif; }

.wrap { max-width: 1180px; margin: 0 auto; padding: 0 28px; }

/* NAV */
nav {
  position: sticky; top: 0; z-index: 100;
  background: rgba(255, 255, 255, 0.94);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid rgba(43, 43, 38, 0.1);
}
nav .wrap {
  display: flex; align-items: center; justify-content: space-between;
  padding-top: 18px; padding-bottom: 18px;
}
.logo { font-family: 'Playfair Display', serif; font-size: 1.6rem; font-weight: 700; text-decoration: none; color: var(--charcoal); }
.logo span { color: var(--orange); }
.nav-links { display: flex; gap: 28px; list-style: none; flex-wrap: wrap; }
.nav-links a { text-decoration: none; color: var(--charcoal); font-weight: 500; font-size: 0.95rem; }
.nav-links a:hover { color: var(--orange); }

/* HERO base spacing (final hero visuals are defined further below) */
.hero p { font-size: 1.15rem; max-width: 640px; margin: 0 auto 28px; }
.btn {
  display: inline-block; padding: 14px 30px; border-radius: 999px;
  font-weight: 700; text-decoration: none; font-size: 1rem;
  background: var(--charcoal); color: var(--white);
  transition: transform 0.15s ease;
}
.btn:hover { transform: translateY(-2px); }
.btn.outline { background: transparent; border: 2px solid var(--charcoal); color: var(--charcoal); }

/* CATEGORY TILES */
.category-grid {
  display: grid; grid-template-columns: repeat(4, 1fr);
  gap: 24px; padding: 56px 0;
}
@media (max-width: 900px) { .category-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 480px) { .category-grid { grid-template-columns: 1fr; } }
.category-tile {
  background: var(--white); border-radius: 18px; padding: 28px 22px;
  text-decoration: none; color: var(--charcoal);
  border: 1px solid rgba(43,43,38,0.08);
  transition: transform 0.15s ease;
}
.category-tile:hover { transform: translateY(-3px); border-color: var(--teal); }
.category-tile h3 { font-size: 1.15rem; margin-bottom: 4px; }
.category-tile p { font-size: 0.85rem; color: var(--charcoal-soft); margin: 0; }

/* PRODUCT GRID */
.product-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 24px; padding: 40px 0 72px;
}
.product-card {
  background: var(--white); border-radius: 18px; overflow: hidden;
  border: 1px solid rgba(43,43,38,0.08);
  display: flex; flex-direction: column;
}
.product-card img { width: 100%; aspect-ratio: 1/1; object-fit: cover; background: #eee; }
.product-card-body { padding: 16px 18px 20px; flex: 1; display: flex; flex-direction: column; }
.product-card h3 { font-size: 1rem; font-family: 'Inter', sans-serif; font-weight: 600; margin-bottom: 6px; }
.product-card .price { color: var(--orange); font-weight: 700; font-size: 1.05rem; margin-bottom: 10px; }
.product-card .vendor { font-size: 0.78rem; color: var(--charcoal-soft); margin-bottom: 10px; }
.product-card .view-btn {
  margin-top: auto; text-align: center; padding: 10px; border-radius: 999px;
  background: var(--teal); color: white; text-decoration: none; font-weight: 600; font-size: 0.9rem;
  cursor: pointer; border: none;
}

/* PAGE HEADER (category pages) */
.page-header { padding: 48px 0 8px; text-align: center; }
.page-header h1 { font-size: clamp(1.8rem, 4vw, 2.6rem); margin-bottom: 8px; }
.page-header p { color: var(--charcoal-soft); }
.back-link { display: inline-block; margin: 24px 0 0; color: var(--teal); text-decoration: none; font-weight: 600; }

/* PRODUCT DETAIL MODAL */
.modal-overlay {
  display: none; position: fixed; inset: 0; background: rgba(43,43,38,0.55);
  z-index: 200; align-items: center; justify-content: center; padding: 20px;
}
.modal-overlay.active { display: flex; }
.modal-box {
  background: var(--white); border-radius: 20px; max-width: 780px; width: 100%;
  max-height: 88vh; overflow-y: auto; display: grid; grid-template-columns: 1fr 1fr;
}
@media (max-width: 640px) { .modal-box { grid-template-columns: 1fr; } }
.modal-box img { width: 100%; height: 100%; object-fit: cover; }
.modal-content { padding: 28px 30px; }
.modal-close {
  position: absolute; top: 16px; right: 20px; background: none; border: none;
  font-size: 1.6rem; cursor: pointer; color: var(--charcoal);
}
.buy-button-slot { margin-top: 20px; min-height: 50px; }
.buy-button-slot .placeholder-note {
  font-size: 0.8rem; color: var(--charcoal-soft); background: #FFF8E1;
  border: 1px dashed var(--yellow); border-radius: 10px; padding: 10px 14px;
}

/* ANNOUNCEMENT BAR */
.announce-bar {
  background: var(--white); text-align: center; font-size: 0.85rem;
  padding: 10px 40px; position: relative; border-bottom: 1px solid rgba(0,0,0,0.06);
}
.announce-bar .arrow { position: absolute; top: 8px; font-size: 1.1rem; cursor: pointer; color: var(--charcoal-soft); }
.announce-bar .arrow:first-child { left: 16px; }
.announce-bar .arrow:last-child { right: 16px; }

/* NAV (updated for logo icon + simple Home/Shop) */
.logo { display: flex; align-items: center; gap: 8px; }
.logo img { height: 88px; width: auto; display: block; }
.logo-text { font-family: 'Playfair Display', serif; font-size: 1.5rem; font-weight: 700; }
.logo-smart { color: var(--yellow); }
.logo-bash { color: var(--teal); }
.nav-icons { display: flex; gap: 18px; font-size: 1.1rem; }

/* HERO (matched to actual site: teal/confetti photo, centered serif headline) */
.hero {
  background: linear-gradient(rgba(20,90,85,0.25), rgba(20,90,85,0.25)),
              url('data:image/jpeg;base64,');
  background-size: cover; background-position: center;
  height: 250px; display: flex; align-items: center; justify-content: center;
  text-align: center;
}
.hero h1 { color: var(--white); font-size: clamp(2rem, 5vw, 3rem); font-style: normal; font-weight: 400; }

/* SECTION ROW HEADER (Celebrate Better / View all) */
.section-row-header {
  display: flex; align-items: baseline; justify-content: space-between;
  padding: 40px 0 20px;
}
.section-row-header h2 { font-size: 1.8rem; font-weight: 500; }
.view-all-link { color: var(--teal); text-decoration: none; font-weight: 500; font-size: 0.9rem; }

/* PRODUCT CAROUSEL */
.product-carousel {
  display: flex; gap: 18px; overflow-x: auto; padding-bottom: 24px;
  scrollbar-width: thin;
}
.product-carousel .product-card { min-width: 220px; max-width: 220px; flex-shrink: 0; }

/* FOOTER (matched to actual store: white bg, Links / newsletter / email signup) */
footer {
  background: var(--white); color: var(--charcoal);
  padding: 56px 0 24px;
}
.footer-grid {
  display: grid; grid-template-columns: 1fr 1.5fr 1.8fr; gap: 40px;
  align-items: start;
}
@media (max-width: 800px) { .footer-grid { grid-template-columns: 1fr; gap: 32px; } }

.footer-links h4 { font-size: 0.95rem; font-weight: 600; margin-bottom: 14px; color: var(--charcoal); }
.footer-links ul { list-style: none; }
.footer-links ul li { margin-bottom: 10px; }
.footer-links ul a { color: var(--charcoal); text-decoration: none; font-size: 0.92rem; }
.footer-links ul a:hover { color: var(--teal); }

.footer-newsletter h3 {
  font-family: 'Playfair Display', serif; font-weight: 400; font-size: 1.6rem;
  margin-bottom: 10px;
}
.footer-newsletter p { color: var(--charcoal-soft); font-size: 0.92rem; max-width: 320px; }

.footer-email-form {
  display: flex; align-items: center; border: 1px solid var(--teal);
  border-radius: 999px; overflow: hidden; max-width: 420px;
}
.footer-email-form input {
  flex: 1; border: none; outline: none; padding: 14px 18px;
  font-size: 0.92rem; font-family: inherit; color: var(--charcoal); background: transparent;
}
.footer-email-form input::placeholder { color: var(--charcoal-soft); }
.footer-email-form button {
  border: none; background: transparent; color: var(--teal);
  font-size: 1.2rem; padding: 0 18px; cursor: pointer;
}

.footer-bottom {
  border-top: 1px solid rgba(43,43,38,0.1); margin-top: 32px; padding-top: 18px;
  text-align: center; font-size: 0.8rem; color: var(--charcoal-soft);
}
